    val ENCODING_ARRAY: Array<String?> = ENCODING.split(",".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
    fun match(pinyin: String?, text: String?): Boolean {
        if (pinyin.isNullOrEmpty()) {
            return true;
        }
        if (text.isNullOrEmpty()) {
            return false;
        }
        if (text.contains(pinyin)) {
            return true;
        }
        var idx = 0
        for (i in 0 until pinyin.length) {
            val p = pinyin[i]
            val isPinyin = (p in 'a'..'z' || p in 'A'..'Z') && !iuv.contains(p)
            var matchIdx = false
            for (n in idx until text.length) {
                val c = text[n]
                if (isPinyin) {
                    if (c.code >= BASE_CODE_POINT && c.code < BASE_CODE_POINT + DATA.length) {
                        val code = DATA[c.code - BASE_CODE_POINT].code - 33
                        if (code >= 0 && ENCODING_ARRAY[code]?.indexOf(p) != -1) {
                            idx = n + 1
                            matchIdx = true
                            break
                        }
                    }
                }
                if (p == text[n]) {
                    idx = n + 1
                    matchIdx = true
                    break
                }
            }
            if (!matchIdx) {
                return false;
            }
        }
        return true
    }
}
